def parse_base(value):
    # ci 乐观并发的 base：小写 64 位十六进制串（ct 输出的配置指纹）；
    # 类型、长度或字符集不符判 INPUT。
    if (
        not isinstance(value, str)
        or len(value) != 64
        or any(char not in "0123456789abcdef" for char in value)
    ):
        fail(EXIT_INPUT, "INPUT")
    return value


